<!--
 * 消息偏好设置列表页组件
 *
 * @path apps/message-web/src/views/preference/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（listByUser/upsert/deleteApi）。
-->
<script lang="ts" setup>
/**
 * 消息偏好（列表页）
 * <p>消费后端契约 PreferenceController（src/api/preference.ts，auto-generated by bash/gen-contract.py）：
 * listByUser({userId}) 查询当前用户的偏好列表（本应用无登录态，暂以 'current' 作为当前用户标识），
 * 行操作「编辑」打开 preference-form.vue、「删除」调 deleteApi({id})。契约无分页，列表按非分页返回。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteApi, listByUser } from '#/api/preference';
import type { MsgPreferenceVO } from '#/api/models';

import PreferenceForm from './preference-form.vue';

defineOptions({ name: 'PreferenceManagement' });

/** 当前用户 ID：本子应用无登录态，暂以 'current' 作为当前用户标识 */
const CURRENT_USER_ID = 'current';

const gridOptions: VxeTableGridOptions<MsgPreferenceVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'userId', title: '用户ID', width: 140 },
    { field: 'channel', title: '通道', width: 110 },
    { field: 'bizType', title: '业务类型', width: 110 },
    {
      field: 'enabled',
      title: '启用',
      width: 80,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.enabled === 1 ? 'success' : 'info' }, () => (row.enabled === 1 ? '启用' : '停用')),
      },
    },
    {
      field: 'dndEnabled',
      title: '免打扰',
      width: 90,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.dndEnabled === 1 ? 'warning' : 'info' }, () => (row.dndEnabled === 1 ? '开启' : '关闭')),
      },
    },
    { field: 'dndStart', title: '免打扰开始', width: 110 },
    { field: 'dndEnd', title: '免打扰结束', width: 110 },
    { field: 'dailyLimit', title: '日上限', width: 90 },
    { field: 'hourlyLimit', title: '时上限', width: 90 },
    {
      field: 'status',
      title: '状态',
      width: 90,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: row.status === 'DISABLED' ? 'info' : 'success' }, () => row.status ?? '-'),
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) }, () => '编辑'),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) }, () => '删除'),
          ]),
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const keyword = String(formValues.channel ?? '').trim();
        const items = await listByUser({ userId: CURRENT_USER_ID });
        const filtered = keyword
          ? items.filter((item) => (item.channel ?? '').includes(keyword))
          : items;
        return { items: filtered, total: filtered.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'channel', title: '通道', itemRender: { name: 'Input', props: { placeholder: '通道' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [PreferenceFormModal, preferenceFormApi] = useYDSZModal({ connectedComponent: PreferenceForm });

function handleAdd() {
  preferenceFormApi.open();
}

function handleEdit(row: MsgPreferenceVO) {
  preferenceFormApi.setData({ record: row });
  preferenceFormApi.open();
}

async function handleDelete(row: MsgPreferenceVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(
      `确定删除「${row.channel} / ${row.bizType ?? '-'}」的偏好设置吗？`,
      '删除确认',
      { type: 'warning' },
    );
    await deleteApi({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="消息偏好">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增</ElButton>
      </template>
    </Grid>
    <PreferenceFormModal @success="gridApi.query()" />
  </Page>
</template>